"use client";

import { useEffect, useState } from "react";
import { readWatchlist, toggleWatchlist } from "@/components/watchlist-store";

export function WatchlistToggle({ symbol }: { symbol: string }) {
  const [inList, setInList] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    setInList(readWatchlist().includes(symbol));
    const handler = () => setInList(readWatchlist().includes(symbol));
    window.addEventListener("watchlist:changed", handler);
    window.addEventListener("storage", handler);
    return () => {
      window.removeEventListener("watchlist:changed", handler);
      window.removeEventListener("storage", handler);
    };
  }, [symbol]);

  if (!mounted) {
    return (
      <button
        className="rounded-md border border-(--color-border) px-3 py-1.5 text-sm text-(--color-text-muted)"
        disabled
      >
        ☆ Watchlist
      </button>
    );
  }

  const handleClick = () => {
    const next = toggleWatchlist(symbol);
    setInList(next);
  };

  return (
    <button
      onClick={handleClick}
      className={`rounded-md border px-3 py-1.5 text-sm font-medium transition-colors ${
        inList
          ? "border-(--color-brand) bg-(--color-brand)/10 text-(--color-brand)"
          : "border-(--color-border) text-(--color-text) hover:border-(--color-brand) hover:text-(--color-brand)"
      }`}
    >
      {inList ? "★ Watching" : "☆ Add to Watchlist"}
    </button>
  );
}

const fs = require('fs');
const path = require('path');

const filePath = path.join(__dirname, '../node_modules/fusioncharts/fusioncharts.js');

try {
  let content = fs.readFileSync(filePath, 'utf8');

  // FusionCharts typically evaluates or draws the watermark text.
  // We can neuter the string "FusionCharts Trial"
  const originalLength = content.length;
  content = content.replace(/FusionCharts Trial/gi, '');
  content = content.replace(/FCHSEvalMark/g, 'REMOVED');

  // Also try to find the specific drawing routine if we can't find the string
  // Let's replace the string "Trial" with "" if it's nearby "FusionCharts"

  fs.writeFileSync(filePath, content, 'utf8');
  console.log('Successfully patched fusioncharts.js. Replaced strings. Size changed from', originalLength, 'to', content.length);
} catch (error) {
  console.error('Failed to patch FusionCharts:', error);
}

