import Link from "next/link";
import { fetchLatestEod, type EodRecord } from "@/lib/marketstack";
import { TRACKED_SYMBOLS, STOCKS_BY_SYMBOL } from "@/lib/stocks";
import { changePercent, formatPlainPrice, formatPercent } from "@/lib/format";

export async function TickerMarquee() {
  let records: EodRecord[] = [];
  try {
    records = await fetchLatestEod(TRACKED_SYMBOLS);
  } catch {
    return null;
  }

  if (records.length === 0) return null;

  const items = records.map((r) => {
    const change = changePercent(r.open, r.close);
    const meta = STOCKS_BY_SYMBOL[r.symbol];
    return { symbol: r.symbol, name: meta?.name ?? r.name, close: r.close, change };
  });

  // Double the items for seamless loop
  const doubled = [...items, ...items];

  return (
    <div className="relative overflow-hidden border-b border-(--color-border) bg-(--color-surface)">
      <div className="marquee-track flex w-max gap-6 py-1.5 px-4">
        {doubled.map((item, i) => (
          <Link
            key={`${item.symbol}-${i}`}
            href={`/stock/${item.symbol}`}
            className="group flex shrink-0 items-center gap-2 text-xs transition-opacity hover:opacity-80"
          >
            <span className="font-semibold text-(--color-text)">
              {item.symbol}
            </span>
            <span className="tabular text-(--color-text-muted)">
              ${formatPlainPrice(item.close)}
            </span>
            <span
              className={`tabular font-medium ${
                item.change >= 0 ? "text-(--color-up)" : "text-(--color-down)"
              }`}
            >
              {formatPercent(item.change)}
            </span>
          </Link>
        ))}
      </div>
    </div>
  );
}

"use client";

const KEY = "stockometer:watchlist";

export function readWatchlist(): string[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((s) => typeof s === "string") : [];
  } catch {
    return [];
  }
}

export function writeWatchlist(symbols: string[]): void {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(KEY, JSON.stringify(symbols));
  window.dispatchEvent(new CustomEvent("watchlist:changed"));
}

export function toggleWatchlist(symbol: string): boolean {
  const list = readWatchlist();
  const idx = list.indexOf(symbol);
  if (idx === -1) {
    list.push(symbol);
    writeWatchlist(list);
    return true;
  }
  list.splice(idx, 1);
  writeWatchlist(list);
  return false;
}

import type { EodRecord } from "@/lib/marketstack";
import { changePercent } from "@/lib/format";
import { STOCKS_BY_SYMBOL, type Sector } from "@/lib/stocks";

export type SectorAggregate = {
  sector: Sector;
  count: number;
  avgChange: number;
  totalVolume: number;
  advancers: number;
  decliners: number;
  topPerformer: { symbol: string; change: number } | null;
  bottomPerformer: { symbol: string; change: number } | null;
  records: EodRecord[];
};

export function aggregateBySector(records: EodRecord[]): SectorAggregate[] {
  const groups = new Map<Sector, EodRecord[]>();
  for (const r of records) {
    const meta = STOCKS_BY_SYMBOL[r.symbol];
    if (!meta) continue;
    const list = groups.get(meta.sector) ?? [];
    list.push(r);
    groups.set(meta.sector, list);
  }

  const result: SectorAggregate[] = [];
  for (const [sector, list] of groups) {
    const changes = list.map((r) => ({
      symbol: r.symbol,
      change: changePercent(r.open, r.close),
    }));
    const avgChange =
      changes.reduce((s, c) => s + c.change, 0) / changes.length;
    const totalVolume = list.reduce((s, r) => s + r.volume, 0);
    const advancers = changes.filter((c) => c.change > 0).length;
    const sortedDesc = [...changes].sort((a, b) => b.change - a.change);
    result.push({
      sector,
      count: list.length,
      avgChange,
      totalVolume,
      advancers,
      decliners: list.length - advancers,
      topPerformer: sortedDesc[0] ?? null,
      bottomPerformer: sortedDesc[sortedDesc.length - 1] ?? null,
      records: list,
    });
  }

  return result.sort((a, b) => b.avgChange - a.avgChange);
}

"use client";

const KEY = "stockometer:portfolio";

export type Holding = {
  symbol: string;
  shares: number;
  avgCost: number;
};

export function readPortfolio(): Holding[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function writePortfolio(holdings: Holding[]): void {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(KEY, JSON.stringify(holdings));
  window.dispatchEvent(new CustomEvent("portfolio:changed"));
}

export function addHolding(holding: Holding): void {
  const list = readPortfolio();
  const existing = list.findIndex(
    (h) => h.symbol === holding.symbol.toUpperCase(),
  );
  if (existing !== -1) {
    // Merge: weighted average cost
    const old = list[existing];
    const totalShares = old.shares + holding.shares;
    const totalCost = old.shares * old.avgCost + holding.shares * holding.avgCost;
    list[existing] = {
      symbol: old.symbol,
      shares: totalShares,
      avgCost: totalCost / totalShares,
    };
  } else {
    list.push({
      ...holding,
      symbol: holding.symbol.toUpperCase(),
    });
  }
  writePortfolio(list);
}

export function removeHolding(symbol: string): void {
  const list = readPortfolio().filter(
    (h) => h.symbol !== symbol.toUpperCase(),
  );
  writePortfolio(list);
}

export function updateHolding(
  symbol: string,
  patch: Partial<Pick<Holding, "shares" | "avgCost">>,
): void {
  const list = readPortfolio();
  const idx = list.findIndex((h) => h.symbol === symbol.toUpperCase());
  if (idx === -1) return;
  list[idx] = { ...list[idx], ...patch };
  writePortfolio(list);
}

