import { useEffect, useState } from "react";
import Image from "next/image";
import { STOCKS_BY_SYMBOL } from "@/lib/stocks";

const PALETTE = [
  ["#2480fc", "#fff"],
  ["#0052cc", "#fff"],
  ["#37c625", "#0b0e11"],
  ["#f6465d", "#fff"],
  ["#9b59f6", "#fff"],
  ["#ff8a3d", "#0b0e11"],
  ["#15c0e8", "#0b0e11"],
  ["#ff5fa3", "#0b0e11"],
];

function hash(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (h * 31 + str.charCodeAt(i)) >>> 0;
  }
  return h;
}

function buildSources(symbol: string, domain?: string): string[] {
  const token = process.env.NEXT_PUBLIC_LOGO_DEV_TOKEN;
  const sources: string[] = [];
  if (domain) {
    if (token) {
      sources.push(
        `https://img.logo.dev/${domain}?token=${token}&size=200&format=png&retina=true`,
      );
    }
    sources.push(
      `https://icons.duckduckgo.com/ip3/${domain}.ico`,
      `https://www.google.com/s2/favicons?domain=${domain}&sz=128`,
    );
  } else if (token) {
    // No curated domain (dynamic universe): let logo.dev resolve by ticker.
    sources.push(
      `https://img.logo.dev/ticker/${symbol}?token=${token}&size=200&format=png&retina=true`,
    );
  }
  return sources;
}

export function TickerIcon({
  symbol,
  size = 32,
  domain,
}: {
  symbol: string;
  size?: number;
  domain?: string;
}) {
  const resolvedDomain = domain ?? STOCKS_BY_SYMBOL[symbol]?.domain;
  const [sourceIdx, setSourceIdx] = useState(0);

  useEffect(() => {
    setSourceIdx(0);
  }, [resolvedDomain]);

  const sources = buildSources(symbol, resolvedDomain);
  if (sourceIdx < sources.length) {
    return (
      <div
        className="grid shrink-0 place-items-center overflow-hidden rounded-full bg-white"
        style={{ width: size, height: size }}
      >
        <Image
          src={sources[sourceIdx]}
          alt={`${symbol} logo`}
          width={size}
          height={size}
          onError={() => setSourceIdx((i) => i + 1)}
          className="h-full w-full rounded-full object-contain"
        />
      </div>
    );
  }

  const [bg, fg] = PALETTE[hash(symbol) % PALETTE.length];
  return (
    <div
      className="grid shrink-0 place-items-center rounded-full font-bold"
      style={{
        width: size,
        height: size,
        background: bg,
        color: fg,
        fontSize: size * 0.4,
      }}
    >
      {symbol.slice(0, 2)}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";

export function LiveRefresh({
  intervalMs = 65_000,
  label = "Live",
}: {
  intervalMs?: number;
  label?: string;
}) {
  const router = useRouter();
  const [pulse, setPulse] = useState(0);
  const lastTickRef = useRef<number>(Date.now());

  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled || document.hidden) return;
      lastTickRef.current = Date.now();
      router.refresh();
      setPulse((p) => p + 1);
    };
    const id = window.setInterval(tick, intervalMs);
    const onVisible = () => {
      if (!document.hidden && Date.now() - lastTickRef.current > intervalMs) {
        tick();
      }
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      cancelled = true;
      window.clearInterval(id);
      document.removeEventListener("visibilitychange", onVisible);
    };
  }, [router, intervalMs]);

  return (
    <span
      key={pulse}
      className="inline-flex items-center gap-1.5 text-xs text-(--color-text-muted)"
      aria-live="polite"
    >
      <span className="relative inline-flex size-2">
        {/* <span className="absolute inset-0 animate-ping rounded-full bg-(--color-up) opacity-75" /> */}
        {/* <span className="relative inline-flex size-2 rounded-full bg-(--color-up)" /> */}
      </span>
      <span>
        {/* {label} · refreshes every {Math.round(intervalMs / 1000)}s */}
      </span>
    </span>
  );
}

export function formatPrice(value: number, currency = "USD"): string {
  const fractionDigits = value < 1 ? 4 : value < 100 ? 2 : 2;
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

export function formatPlainPrice(value: number): string {
  return new Intl.NumberFormat("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);
}

export function formatCompact(value: number): string {
  return new Intl.NumberFormat("en-US", {
    notation: "compact",
    maximumFractionDigits: 2,
  }).format(value);
}

export function formatPercent(value: number): string {
  const sign = value > 0 ? "+" : "";
  return `${sign}${value.toFixed(2)}%`;
}

export function changePercent(open: number, close: number): number {
  if (!open) return 0;
  return ((close - open) / open) * 100;
}

export function formatDate(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

import type { EodRecord } from "@/lib/marketstack";
import { changePercent, formatCompact } from "@/lib/format";

export function MarketStatsBar({ records }: { records: EodRecord[] }) {
  if (records.length === 0) return null;

  const totalVolume = records.reduce((sum, r) => sum + r.volume, 0);
  const advancers = records.filter(
    (r) => changePercent(r.open, r.close) > 0,
  ).length;
  const decliners = records.length - advancers;
  const latestDate = records[0]?.date;

  return (
    <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs text-(--color-text-muted)">
      <span>
        Tracking{" "}
        <span className="text-(--color-text) font-medium">{records.length}</span>{" "}
        tickers
      </span>
      <span>
        <span className="text-(--color-up) font-medium">▲ {advancers}</span>{" "}
        advancing
      </span>
      <span>
        <span className="text-(--color-down) font-medium">▼ {decliners}</span>{" "}
        declining
      </span>
      <span>
        Total volume{" "}
        <span className="text-(--color-text) font-medium tabular">
          {formatCompact(totalVolume)}
        </span>
      </span>
      {latestDate && (
        <span>
          As of{" "}
          <span className="text-(--color-text) tabular">
            {new Date(latestDate).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
              year: "numeric",
            })}
          </span>
        </span>
      )}
    </div>
  );
}

